use super::*;
use std::io::Write;
use std::sync::atomic::{AtomicU64,Ordering};
use baal_portfolio_engine::{canonical_hash,event_group,portfolio_policy,receipt_fill_policy};
fn at(ms:i64)->String{chrono::DateTime::from_timestamp_millis(ms).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn base()->i64{chrono::DateTime::parse_from_rfc3339("2026-10-05T20:00:00.000Z").unwrap().timestamp_millis()}
fn append(path:&Path,value:&Value){let mut f=fs::OpenOptions::new().create(true).append(true).open(path).unwrap();f.write_all(js_stringify(value).as_bytes()).unwrap();f.write_all(b"\n").unwrap();f.sync_all().unwrap();}
struct Fixture{root:PathBuf,config:ObserverConfig,publisher:Publisher,account_sequence:u64,account_hash:String}
impl Fixture{
 fn new()->Self{static SERIAL:AtomicU64=AtomicU64::new(0);let root=std::env::temp_dir().join(format!("baal-paper-observer-{}-{}-{}",std::process::id(),chrono::Utc::now().timestamp_millis(),SERIAL.fetch_add(1,Ordering::SeqCst)));let cohort=root.join("settlement-portfolio-v3-cohorts/fixture");fs::create_dir_all(&cohort).unwrap();
  let universe=json!({"tournamentId":"bda92870-621e-47b0-bc3c-3602c5c26f55","exchanges":[{"marketId":"1","exchangeId":"101","option":"YES"}]});let mut publisher=Publisher::new(&universe).unwrap();let initial=publisher.next_record("session_start",json!({"scope":publisher.status()["scope"]}),&at(base()),"fixture").unwrap();publisher.apply_record(&initial).unwrap();let public=root.join("public-books.jsonl");append(&public,&initial);let account=root.join("account-eligibility.jsonl");fs::write(&account,b"").unwrap();
  let contract=json!({"node_id":"11","contract_id":"11","node_type":"contract","contract_type":"Election Outcome","settled_with":null,"settlement_date":at(base()+30*86400000),"contract_details":{"raceId":"101","stageId":"201","usState":"ZZ","raceStage":"General","officeLevel":"Federal","electionDate":"2026-11-03","resolutionType":"Party Winner","winnerName":"Democratic Party"}});
  let research=json!({"schemaVersion":1,"id":"fixture","marketId":"1","exchangeId":"101","side":"YES","predicateHash":canonical_hash(&contract),"recordedAt":at(base()-1000),"sourceAt":at(base()-1000),"expiresAt":at(base()+21600000),"lower":"0.800000","upper":"0.900000","method":"subjective_range","settlementReviewed":true,"flags":[],"sources":[{"url":"https://example.org/correctness-fixture","contentHash":"b".repeat(64)}]});let evidence=json!([{"researchId":"fixture","marketId":"1","root":contract,"rootHash":research["predicateHash"]}]);
  let code=root.join("synthetic-code.rs");fs::write(&code,b"Synthetic correctness pin only").unwrap();let binary=root.join("synthetic-binary.exe");fs::write(&binary,b"Not an executable, only an immutable fixture pin").unwrap();let code_hash=sha(&fs::read(&code).unwrap());let binary_hash=sha(&fs::read(&binary).unwrap());
  let bank=json!({"schemaVersion":3,"mode":RECEIPT_BASELINE_MODE,"name":"fixture","cutoff":at(base()+1000),"universe":universe,"identities":{"1":{"exchangeId":"101","predicateHash":research["predicateHash"]}},"research":[research],"researchEvidence":evidence,"riskGroups":{"1":["national_election",event_group(&contract).unwrap()]},"valuationDeadlineMs":base()+30*86400000,"policy":portfolio_policy(&evidence).unwrap(),"fillPolicy":receipt_fill_policy(),"sourcePrefixBytes":fs::metadata(&public).unwrap().len(),"sourcePrefixHash":prefix_sha(&public,fs::metadata(&public).unwrap().len()).unwrap(),"sourcePrefixSequence":publisher.status()["sequence"],"sourcePrefixJournalHash":publisher.status()["hash"],"codeIdentity":{"language":"Rust","engineHash":baal_portfolio_engine::engine_hash(),"binaryHash":binary_hash,"sources":{"fixture.rs":code_hash}}});let bank_path=cohort.join("bank.json");fs::write(&bank_path,js_stringify(&bank)).unwrap();
  let config=ObserverConfig{cohort_dir:cohort,bank_path:bank_path.clone(),bank_file_hash:sha(&fs::read(&bank_path).unwrap()),bank_hash:digest(&bank),public_source_path:public,account_source_path:account,account_universe_hash:"a".repeat(64),stop_paths:vec![],code_pins:vec![SourcePin{path:code,sha256:code_hash},SourcePin{path:binary,sha256:binary_hash}],entry_enabled:true,entry_drain_path:Some(root.join("ENTRY_DRAIN"))};Self{root,config,publisher,account_sequence:0,account_hash:String::new()}
 }
 fn account(&mut self,known_ms:i64,excluded:bool){self.account_sequence+=1;let mut body=json!({"sequence":self.account_sequence,"previous":self.account_hash,"at":at(base()+known_ms),"event":{"type":"market_account_eligibility","snapshot":{"tournamentId":"bda92870-621e-47b0-bc3c-3602c5c26f55","universeHash":"a".repeat(64),"positionsAt":at(base()+known_ms-200),"ordersAt":at(base()+known_ms-100),"expiresAt":at(base()+known_ms-200+20000),"excludedMarketIds":if excluded{json!(["1"])}else{json!([])},"complete":true}},"state":null});let hash=digest(&body);body["hash"]=json!(hash);append(&self.config.account_source_path,&body);self.account_hash=hash;}
 fn book(&mut self,request_ms:i64,sequence:u64){let received=at(base()+request_ms+100);let source=chrono::DateTime::from_timestamp_millis(base()+request_ms).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Nanos,true);let book=json!({"tournamentId":"bda92870-621e-47b0-bc3c-3602c5c26f55","marketId":"1","exchangeId":"101","instrument":"101:YES","receivedAt":received,"requestStartedAt":at(base()+request_ms),"sourceAt":source,"sequence":sequence.to_string(),"versionKey":format!("{sequence}:{source}"),"bids":[{"price":"0.345000","quantity":1000}],"asks":[{"price":"0.350000","quantity":1000}],"freshnessPolicy":"authoritative_receipt_v1","sourceEventAgeMs":100});let row=self.publisher.next_record("book",json!({"book":book}),&received,"fixture").unwrap();self.publisher.apply_record(&row).unwrap();append(&self.config.public_source_path,&row);}
}
impl Drop for Fixture{fn drop(&mut self){let _=fs::remove_dir_all(&self.root);}}

#[test]fn one_shot_actual_consumer_restart_preserves_raw_receipt_fills(){let mut f=Fixture::new();f.account(2900,false);f.book(3000,1);let mut observer=Observer::open(f.config.clone()).unwrap();let first=observer.consume_once(&at(base()+3200),10).unwrap();assert_eq!(first["consumedRows"],1);let report=observer.status(&at(base()+3200)).unwrap();assert_eq!(report["wallets"]["1000"]["fills"],0);assert_eq!(report["observer"]["clockModel"],"actual_native_observer_batch_receipt");drop(observer);f.account(7900,false);f.book(8000,2);let mut observer=Observer::open(f.config.clone()).unwrap();observer.consume_once(&at(base()+8200),10).unwrap();let report=observer.status(&at(base()+8200)).unwrap();for latency in ["1000","3000"]{assert_eq!(report["wallets"][latency]["cash"],"99.650000");assert_eq!(report["wallets"][latency]["fills"],1);assert_eq!(report["wallets"][latency]["positions"][0]["cost"],"0.350000");}assert_eq!(report["networkRequests"],0);drop(observer);let observer=Observer::open(f.config.clone()).unwrap();assert_eq!(observer.status(&at(base()+8200)).unwrap()["stateHash"],report["stateHash"]);}
#[test]fn future_account_snapshot_cannot_backfill_a_past_book(){let mut f=Fixture::new();f.book(3000,1);f.account(4000,false);let mut observer=Observer::open(f.config.clone()).unwrap();observer.consume_once(&at(base()+4200),10).unwrap();let report=observer.status(&at(base()+4200)).unwrap();assert_eq!(report["wallets"]["1000"]["fills"],0);assert!(report["wallets"]["1000"]["pending"].as_array().unwrap().is_empty());}
#[test]fn late_actual_consumer_does_not_timelapse_old_receipts_into_live_fills(){let mut f=Fixture::new();f.account(2900,false);f.book(3000,1);f.account(7900,false);f.book(8000,2);let mut observer=Observer::open(f.config.clone()).unwrap();observer.consume_once(&at(base()+40000),10).unwrap();let report=observer.status(&at(base()+40000)).unwrap();assert_eq!(report["wallets"]["1000"]["cash"],"100.000000");assert_eq!(report["wallets"]["1000"]["fills"],0);}
#[test]fn unknown_self_liquidity_exclusions_block_the_counterfactual_entry(){let mut f=Fixture::new();f.account(2900,true);f.book(3000,1);let mut observer=Observer::open(f.config.clone()).unwrap();observer.consume_once(&at(base()+3200),10).unwrap();assert!(observer.status(&at(base()+3200)).unwrap()["wallets"]["1000"]["pending"].as_array().unwrap().is_empty());}
#[test]fn actor_overlap_stop_and_pinned_code_mutation_fail_closed(){let mut f=Fixture::new();f.account(2900,false);f.book(3000,1);let mut observer=Observer::open(f.config.clone()).unwrap();assert!(Observer::open(f.config.clone()).is_err());fs::write(f.config.cohort_dir.join("STOP"),b"Human stop fixture").unwrap();assert!(observer.consume_once(&at(base()+3200),10).is_err());drop(observer);fs::remove_file(f.config.cohort_dir.join("STOP")).unwrap();fs::write(&f.config.code_pins[0].path,b"changed code").unwrap();assert!(Observer::open(f.config.clone()).is_err());}
#[test]fn original_source_tampering_is_not_repaired(){let mut f=Fixture::new();f.account(2900,false);f.book(3000,1);{let mut observer=Observer::open(f.config.clone()).unwrap();observer.consume_once(&at(base()+3200),10).unwrap();}let original=fs::read(&f.config.public_source_path).unwrap();let changed=String::from_utf8(original).unwrap().replace("0.350000","0.355000");fs::write(&f.config.public_source_path,changed).unwrap();assert!(Observer::open(f.config.clone()).is_err());}
#[test]fn drain_stays_latched_after_marker_deletion_and_keeps_pending_owned_fill(){let mut f=Fixture::new();f.account(2900,false);f.book(3000,1);{let mut observer=Observer::open(f.config.clone()).unwrap();observer.consume_once(&at(base()+3200),10).unwrap();}fs::write(f.config.entry_drain_path.as_ref().unwrap(),b"Operator drain fixture").unwrap();f.account(7900,false);f.book(8000,2);{let mut observer=Observer::open(f.config.clone()).unwrap();observer.consume_once(&at(base()+8200),10).unwrap();let report=observer.status(&at(base()+8200)).unwrap();assert_eq!(report["wallets"]["1000"]["fills"],1);assert_eq!(report["observer"]["entryDraining"],true);}fs::remove_file(f.config.entry_drain_path.as_ref().unwrap()).unwrap();let observer=Observer::open(f.config.clone()).unwrap();assert_eq!(observer.status(&at(base()+8200)).unwrap()["observer"]["entryDraining"],true);}
#[test]fn zero_genesis_state_never_touches_original_v1_v2_wallets(){let f=Fixture::new();let original=f.root.join("old-v1-wallet.json");fs::write(&original,b"old attributed wallet fixture").unwrap();let before=fs::read(&original).unwrap();{let observer=Observer::open(f.config.clone()).unwrap();let report=observer.status(&at(base()+2000)).unwrap();assert_eq!(report["wallets"]["1000"]["cash"],"100.000000");assert_eq!(report["wallets"]["1000"]["fills"],0);assert_eq!(report["observer"]["journalSequence"],1);}assert_eq!(fs::read(&original).unwrap(),before);}
